import { exportToCanvas } from '@excalidraw/excalidraw'

export async function sceneToPng(elements, appState, files): Promise<Blob> {
  const canvas = await exportToCanvas({ elements, appState, files, getDimensions: () => ({ width: 1024, height: 768, scale: 2 }) })
  return new Promise((res) => canvas.toBlob((b) => res(b!), 'image/png'))
}

