import { ai } from '@/lib/ai'
import { z } from 'zod'
const Layout = z.object({ nodes: z.array(z.object({ id: z.string(), label: z.string(), x: z.number(), y: z.number(), w: z.number(), h: z.number() })), edges: z.array(z.object({ from: z.string(), to: z.string() })) })
export async function tidySketch(pngBase64: string) {
  const stream = await ai.stream({ messages: [{ role: 'user', content: [{ type: 'image', image: pngBase64 }, { type: 'text', text: 'Return ONLY JSON {nodes,edges}; coords normalized 0..1.' }] }] })
  let text = ''
  for await (const e of stream) if (e.type === 'text_delta') text += e.text
  return Layout.parse(JSON.parse(text))
}
EOF"}

