import { nanoid } from 'nanoid'
export function layoutToElements(layout, vw, vh) {
  const byId = {}
  const rects = layout.nodes.map((n) => { const id = nanoid(); byId[n.id] = id; return { id, type: 'rectangle', x: n.x*vw, y: n.y*vh, width: n.w*vw, height: n.h*vh, label: { text: n.label } } })
  const arrows = layout.edges.map((e) => ({ id: nanoid(), type: 'arrow', startBinding: { elementId: byId[e.from], focus: 0, gap: 4 }, endBinding: { elementId: byId[e.to], focus: 0, gap: 4 } }))
  return [...rects, ...arrows]
}
EOF"}
